const triggerData = $('GitHub Issues Trigger').first().json;
const body = triggerData.body || triggerData;
const issue = body.issue || body;
const repo = triggerData.repository || body.repository || {};

const issueNum = issue.number || 1;
const issueTitle = issue.title || 'Bug Report';
const issueBody = issue.body || '';
const repoFullName = repo.full_name || 'Vyvch/drop_ru_domain_finder';
const suffix = Math.floor(Date.now() / 1000).toString().slice(-4);

return {
  json: {
    issue_number: issueNum,
    issue_title: issueTitle,
    issue_body: issueBody,
    repo_full_name: repoFullName,
    branch_name: `fix/issue-${issueNum}-autofix-${suffix}`
  }
};

let raw = $json.text || $json.output || '';
let parsed = {};

try {
  let clean = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  const first = clean.indexOf('{');
  const last = clean.lastIndexOf('}');
  if (first !== -1 && last !== -1) {
    clean = clean.substring(first, last + 1);
  }
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = {};
}

const mainTree = $('Fetch Repo Tree (GitHub API)').first().json;
const availableFiles = (mainTree.tree || []).filter(item => item.path && !item.path.startsWith('.')).map(item => item.path);

let files = Array.isArray(parsed.target_files) ? parsed.target_files : [];
// Оставляем только те файлы, которые реально существуют в дереве репозитория
files = files.filter(f => typeof f === 'string' && availableFiles.includes(f));

// Если среди файлов есть тесты, ставим файл исходного кода на первое место (primary_file)
const nonTestFiles = files.filter(f => !f.startsWith('tests/'));
const primaryFile = nonTestFiles.length > 0 ? nonTestFiles[0] : (files[0] || 'domain_exporter.py');

return {
  json: {
    target_files: files.length > 0 ? files : [primaryFile],
    primary_file: primaryFile,
    plan: parsed.plan || 'Автономное исправление ошибки',
    tree_sha: mainTree.sha
  }
};

const contentB64 = $json.content || '';
const rawCode = Buffer.from(contentB64.replace(/\n/g, ''), 'base64').toString('utf-8');
const meta = $('Extract Dynamic Issue Data').first().json;
const filesMeta = $('Parse Target Files List').first().json;

return {
  json: {
    original_code: rawCode,
    file_sha: $json.sha,
    target_files: filesMeta.target_files,
    primary_file: filesMeta.primary_file,
    plan: filesMeta.plan,
    tree_sha: filesMeta.tree_sha,
    issue_number: meta.issue_number,
    issue_title: meta.issue_title,
    issue_body: meta.issue_body,
    branch_name: meta.branch_name,
    attempt: 1,
    max_attempts: 3,
    critique: '',
    verdict: 'PENDING'
  }
};

