let fixedText = $json.text || $json.output || '';
fixedText = fixedText.replace(/```python/gi, '').replace(/```/g, '').trim();

let baseState;
try {
  baseState = $('Evaluate Judge Verdict').last().json;
} catch (e) {
  baseState = $('Init Self-Correction State').first().json;
}

return {
  json: {
    ...baseState,
    candidate_code: fixedText
  }
};

let raw = $json.text || $json.output || '';
let parsed = {};

try {
  let clean = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  const first = clean.indexOf('{');
  const last = clean.lastIndexOf('}');
  if (first !== -1 && last !== -1) {
    clean = clean.substring(first, last + 1);
  }
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = { verdict: 'REJECTED', reason: 'Failed to parse review format' };
}

const candidate = $('Format Candidate Fix').first().json;
const currentAttempt = candidate.attempt || 1;
const maxAttempts = candidate.max_attempts || 3;

let verdict = (parsed.verdict || 'REJECTED').toUpperCase().trim();
let isApproved = verdict === 'APPROVED';
let isLimitReached = !isApproved && (currentAttempt >= maxAttempts);

return {
  json: {
    ...candidate,
    verdict: verdict,
    critique: parsed.reason || 'Замечания не указаны',
    is_approved: isApproved,
    attempt: currentAttempt + 1,
    max_attempts: maxAttempts,
    is_limit_reached: isLimitReached
  }
};

const item = $json;
const fixedB64 = Buffer.from(item.candidate_code, 'utf-8').toString('base64');
const meta = $('Extract Dynamic Issue Data').first().json;

return {
  json: {
    fixed_content_b64: fixedB64,
    original_sha: item.file_sha,
    target_file: item.primary_file,
    all_target_files: item.target_files,
    issue_number: item.issue_number,
    issue_title: item.issue_title,
    branch_name: item.branch_name,
    repo_full_name: meta.repo_full_name,
    judge_critique: item.critique
  }
};

